async function fetchJson(u: string) {
  try { const r = await tools.web_fetch({ url: u }); return JSON.parse(r.body.content); }
  catch (e) { return { error: String(e).slice(0, 300) }; }
}
const [repo, readme] = await Promise.all([
  fetchJson("https://api.github.com/repos/Ebony-Vinyl/dsh-our-free-model"),
  fetchJson("https://api.github.com/repos/Ebony-Vinyl/dsh-our-free-model/readme"),
]);
if (repo && !repo.error) {
  console.log("REPO:", JSON.stringify({ full_name: repo.full_name, stars: repo.stargazers_count, forks: repo.forks_count, watchers: repo.subscribers_count, open_issues: repo.open_issues_count, created: repo.created_at, updated: repo.pushed_at, desc: repo.description, topics: repo.topics, license: repo.license?.spdx_id }, null, 1));
} else console.log("REPO ERR:", JSON.stringify(repo).slice(0,300));
if (readme?.content) {
  const md = Buffer.from(readme.content, "base64").toString("utf8");
  console.log("README (first 5000):\n", md.slice(0, 5000));
} else console.log("README ERR:", JSON.stringify(readme).slice(0,300));
